using TownOfHost;using TownOfHost.Modules.ChatManager;
class Program{
static int passed;static PlayerControl host,target;static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Setup(){host=new(){PlayerId=0,ClientId=0};target=new(){PlayerId=1,ClientId=41};PlayerControl.LocalPlayer=host;PlayerCatch.AllPlayerControls=new(){host,target};TownOfHost.Main.MessagesToSend.Clear();TownOfHost.Main.MegCount=0;TownOfHost.Main.LastNotifyNames.Clear();CustomRpcSender.SentTargets.Clear();HudManager.Instance.Chat.Count=0;Utils.Restriction=false;GameStates.CalledMeeting=true;GameStates.IsMeeting=true;Options.ExHideChatCommand.Enabled=false;ChatUpdatePatch.DoBlockChat=false;}
static void Test(string n,Action a){Setup();a();passed++;Console.WriteLine("PASS "+n);}static void Dispatch(int kind,byte id=1){TownOfHost.Main.MessagesToSend.Add(("private body",id,"<color=red>private title</color>"));if(kind==0)ChatManager.SendMessageInGame(new());else if(kind==1)ChatManager.SendmessageInLobby(new());else ChatManager.IntaskCheckSendMessage(host);}
static void Main(){for(int route=0;route<3;route++){int k=route;Test($"route {k}: unresolved client cannot broadcast",()=>{target.ClientId=-1;Dispatch(k);Check(CustomRpcSender.SentTargets.Count==0&&HudManager.Instance.Chat.Count==0&&TownOfHost.Main.MessagesToSend.Count==0,"private message escaped");});Test($"route {k}: departed player cannot receive",()=>{target.Data.Disconnected=true;Dispatch(k);Check(CustomRpcSender.SentTargets.Count==0&&TownOfHost.Main.MessagesToSend.Count==0,"departed recipient");});Test($"route {k}: missing player cannot broadcast",()=>{PlayerCatch.AllPlayerControls.Remove(target);Dispatch(k);Check(CustomRpcSender.SentTargets.Count==0&&TownOfHost.Main.MessagesToSend.Count==0,"missing recipient");});Test($"route {k}: missing player data cannot broadcast",()=>{target.Data=null;Dispatch(k);Check(CustomRpcSender.SentTargets.Count==0,"missing data");});Test($"route {k}: dummy cannot broadcast",()=>{target.Dummy=true;Dispatch(k);Check(CustomRpcSender.SentTargets.Count==0,"dummy recipient");});Test($"route {k}: valid target remains private",()=>{Dispatch(k);Check(CustomRpcSender.SentTargets.Count==1&&CustomRpcSender.SentTargets[0]==41&&TownOfHost.Main.MessagesToSend.Count==0,"private delivery");});}
Test("hidden command branch skips missing clients",()=>{Options.ExHideChatCommand.Enabled=true;target.ClientId=-1;Dispatch(0);Check(CustomRpcSender.SentTargets.Count==0,"hidden branch");});
Test("hidden command branch targets only valid recipient",()=>{Options.ExHideChatCommand.Enabled=true;Dispatch(0);Check(CustomRpcSender.SentTargets.SequenceEqual(new[]{41}),"hidden recipient");});
Test("restriction and living host retain private target",()=>{Utils.Restriction=true;Dispatch(0);Check(CustomRpcSender.SentTargets.SequenceEqual(new[]{41}),"restriction");});
Test("restriction and dead host skip disconnected clients",()=>{Utils.Restriction=true;host.Alive=false;target.ClientId=-1;Dispatch(0);Check(CustomRpcSender.SentTargets.Count==0,"dead host");});
Test("broadcast lobby message remains broadcast",()=>{Dispatch(1,byte.MaxValue);Check(CustomRpcSender.SentTargets.SequenceEqual(new[]{-1})&&HudManager.Instance.Chat.Count==1,"broadcast");});
Test("task broadcast uses valid per-client envelopes only",()=>{GameStates.CalledMeeting=false;target.ClientId=-1;Dispatch(0,byte.MaxValue);Check(CustomRpcSender.SentTargets.SequenceEqual(new[]{0}),"per-client broadcast");});
Test("local private message never becomes broadcast",()=>{Dispatch(1,0);Check(CustomRpcSender.SentTargets.SequenceEqual(new[]{0}),"local private target");});
Console.WriteLine($"RESULT {passed} passed, 0 failed");}}
